const body = $json.body || $json;
const ALLOWED_STATUSES = ['PENDING', 'IN_PROGRESS', 'READY_FOR_MANUFACTURING', 'FAILED'];

if (!body.acquisition_job_id) {
  throw new Error('acquisition_job_id is required');
}

if (body.status !== undefined && !ALLOWED_STATUSES.includes(body.status)) {
  throw new Error('status must be one of: ' + ALLOWED_STATUSES.join(', '));
}

for (const key of ['rows_processed', 'rows_valid', 'rows_invalid']) {
  const value = body[key];
  if (value !== undefined && value !== null && (typeof value !== 'number' || value < 0)) {
    throw new Error(key + ' must be a non-negative number');
  }
}

// workbook_id, mapping_profile_id, and started_at are fixed at Create time
// -- only a job's execution result progresses (WP-000 design decision 6).
const updatable = [
  'status', 'completed_at', 'rows_processed', 'rows_valid', 'rows_invalid', 'error_summary'
];

const fields = {};
for (const key of updatable) {
  if (body[key] !== undefined) {
    fields[key] = body[key];
  }
}

if (Object.keys(fields).length === 0) {
  throw new Error('at least one updatable field is required');
}

return [{
  json: {
    acquisition_job_id: body.acquisition_job_id,
    fields
  }
}];

const { acquisition_job_id, fields } = $json;
const keys = Object.keys(fields);

const setClauses = keys.map((key, idx) => `${key} = $${idx + 1}`);
setClauses.push('updated_at = NOW()');

const params = keys.map((key) => fields[key]);
params.push(acquisition_job_id);

const query = `UPDATE acquisition_job SET ${setClauses.join(', ')} WHERE acquisition_job_id = $${params.length} RETURNING *;`;

return [{
  json: {
    acquisition_job_id,
    query,
    params
  }
}];

const row = $input.first()?.json;

if (!row || !row.acquisition_job_id) {
  return [{
    json: {
      statusCode: 404,
      success: false,
      message: 'Acquisition job not found',
      data: null
    }
  }];
}

return [{
  json: {
    statusCode: 200,
    success: true,
    message: 'Acquisition job updated successfully',
    data: row
  }
}];
